const DATA={"cleric":{"0":[{"n":"Create Water","s":"Conjuration","d":"Creates 2 gallons/level of pure water."},{"n":"Cure Minor Wounds","s":"Conjuration","d":"Cures 1 point of damage."},{"n":"Detect Magic","s":"Divination","d":"Detects magical auras within 60 ft."},{"n":"Detect Poison","s":"Divination","d":"Detects poison in a creature or object."},{"n":"Guidance","s":"Divination","d":"+1 competence bonus on one attack roll, saving throw, or skill check, chosen before the roll."},{"n":"Inflict Minor Wounds","s":"Necromancy","d":"Touch attack deals 1 point of damage (Will negates)."},{"n":"Light","s":"Evocation","d":"Object glows like a torch: bright light in a 20-ft. radius, dim light 20 ft. farther."},{"n":"Mending","s":"Transmutation","d":"Repairs minor damage to an object."},{"n":"Purify Food and Drink","s":"Transmutation","d":"Purifies food and water."},{"n":"Read Magic","s":"Divination","d":"Reads magical inscriptions on scrolls and spellbooks."},{"n":"Resistance","s":"Abjuration","d":"Subject gains a +1 resistance bonus on all saving throws."},{"n":"Virtue","s":"Transmutation","d":"Subject gains 1 temporary hit point."}],"1":[{"n":"Bane","s":"Enchantment","d":"Enemies take a −1 penalty on attack rolls and on saves against fear."},{"n":"Bless","s":"Enchantment","d":"Allies gain a +1 morale bonus on attack rolls and on saves against fear."},{"n":"Bless Water","s":"Transmutation","d":"Turns a 1-pint flask of water into holy water (uses 25 gp of powdered silver)."},{"n":"Cause Fear","s":"Necromancy","d":"One creature of 5 HD or less is frightened for 1d4 rounds; on a successful Will save it is shaken for 1 round."},{"n":"Command","s":"Enchantment","d":"One subject obeys a one-word command for 1 round."},{"n":"Comprehend Languages","s":"Divination","d":"Understand spoken and written languages."},{"n":"Cure Light Wounds","s":"Conjuration","d":"Cures 1d8 damage +1/level, maximum +5."},{"n":"Curse Water","s":"Transmutation","d":"Turns a 1-pint flask of water into unholy water (uses 25 gp of powdered silver)."},{"n":"Deathwatch","s":"Necromancy","d":"Shows whether each creature within 30 ft. is dead, near death (3 hp or less), alive, undead, or neither."},{"n":"Detect Chaos/Evil/Good/Law","s":"Divination","d":"Reveals creatures, spells, or objects of a selected alignment."},{"n":"Detect Undead","s":"Divination","d":"Reveals undead within 60 ft."},{"n":"Divine Favor","s":"Evocation","d":"You gain a +1 luck bonus on attack and weapon damage rolls per three caster levels (min +1, max +3)."},{"n":"Doom","s":"Necromancy","d":"Subject is shaken: −2 penalty on attack rolls, saves, skill checks, and ability checks."},{"n":"Endure Elements","s":"Abjuration","d":"Subject is comfortable between −50 °F and 140 °F with no Fortitude saves; gives no protection from fire or cold damage."},{"n":"Entropic Shield","s":"Abjuration","d":"Ranged attacks against you have a 20% miss chance."},{"n":"Hide from Undead","s":"Abjuration","d":"Undead cannot perceive the protected subjects."},{"n":"Inflict Light Wounds","s":"Necromancy","d":"Touch deals 1d8 damage +1/level, maximum +5."},{"n":"Magic Stone","s":"Transmutation","d":"Three stones gain +1 on attack rolls and deal increased damage."},{"n":"Magic Weapon","s":"Transmutation","d":"Weapon gains a +1 enhancement bonus."},{"n":"Obscuring Mist","s":"Conjuration","d":"Fog surrounds you and obscures vision."},{"n":"Protection from Chaos/Evil/Good/Law","s":"Abjuration","d":"+2 deflection bonus to AC and +2 resistance bonus on saves against creatures of the chosen alignment; blocks possession and mental control; keeps summoned creatures of that alignment from touching the subject."},{"n":"Remove Fear","s":"Abjuration","d":"+4 morale bonus on saves against fear for 10 minutes; suppresses fear the subject already has."},{"n":"Sanctuary","s":"Abjuration","d":"Opponents must make a Will save to attack the warded creature; the ward ends if it attacks."},{"n":"Shield of Faith","s":"Abjuration","d":"+2 deflection bonus to AC, +1 more per six caster levels (max +5 at 18th level)."},{"n":"Summon Monster I","s":"Conjuration","d":"Summons one creature from the 1st-level summon monster list to fight for you."}],"2":[{"n":"Aid","s":"Abjuration","d":"+1 morale bonus on attack rolls and on saves against fear, plus 1d8 + 1 per caster level temporary hit points (max 1d8 + 10)."},{"n":"Align Weapon","s":"Transmutation","d":"Weapon gains a chosen alignment for overcoming damage reduction."},{"n":"Augury","s":"Divination","d":"Tells you whether an action in the next half hour brings weal, woe, both, or nothing; 70% + 1% per caster level chance of a meaningful answer (max 90%)."},{"n":"Bear's Endurance","s":"Transmutation","d":"Subject gains +4 Constitution."},{"n":"Bull's Strength","s":"Transmutation","d":"Subject gains +4 Strength."},{"n":"Calm Emotions","s":"Enchantment","d":"Calms creatures in a 20-ft. radius: no violent actions; suppresses morale bonuses, rage, and fear and removes confusion."},{"n":"Consecrate","s":"Evocation","d":"20-ft. area: +3 sacred bonus on turning checks; undead in it take −1 on attack rolls, damage rolls, and saves (doubled with an altar of your deity)."},{"n":"Cure Moderate Wounds","s":"Conjuration","d":"Cures 2d8 damage +1/level, maximum +10."},{"n":"Darkness","s":"Evocation","d":"Object radiates shadowy illumination in a 20-ft. radius; creatures in it have concealment (20% miss chance)."},{"n":"Death Knell","s":"Necromancy","d":"Kills a dying creature (Will negates); you gain 1d8 temporary hit points, +2 Strength, and +1 effective caster level for 10 min. per its HD."},{"n":"Delay Poison","s":"Conjuration","d":"Subject is unaffected by poison for 1 hour per level; the poison takes effect when the spell ends."},{"n":"Desecrate","s":"Evocation","d":"20-ft. area: −3 profane penalty on turning checks; undead in it gain +1 profane bonus on attack rolls, damage rolls, and saves (doubled with an altar)."},{"n":"Eagle's Splendor","s":"Transmutation","d":"Subject gains +4 Charisma."},{"n":"Enthrall","s":"Enchantment","d":"Captivates creatures that can hear you."},{"n":"Find Traps","s":"Divination","d":"You find traps with Search as a rogue does and gain an insight bonus of half your caster level on those checks (max +10)."},{"n":"Gentle Repose","s":"Necromancy","d":"Preserves a corpse against decay and effects that raise the dead."},{"n":"Hold Person","s":"Enchantment","d":"Paralyzes one humanoid; it can attempt a new Will save each round."},{"n":"Inflict Moderate Wounds","s":"Necromancy","d":"Touch deals 2d8 damage +1/level, maximum +10."},{"n":"Make Whole","s":"Transmutation","d":"Repairs an object."},{"n":"Owl's Wisdom","s":"Transmutation","d":"Subject gains +4 Wisdom."},{"n":"Remove Paralysis","s":"Abjuration","d":"Ends paralysis or slow on one creature, or gives two creatures a new save at +4 (three or four creatures at +2)."},{"n":"Resist Energy","s":"Abjuration","d":"Subject gains resistance 10 to one energy type (acid, cold, electricity, fire, or sonic); 20 at caster level 7, 30 at 11."},{"n":"Lesser Restoration","s":"Conjuration","d":"Dispels a magical penalty to one ability score or cures 1d4 points of ability damage; ends fatigue and eases exhaustion."},{"n":"Shatter","s":"Evocation","d":"Breaks brittle nonmagical objects in a 5-ft. radius or one object; a crystalline creature takes 1d6 sonic per level (max 10d6, Fort half)."},{"n":"Shield Other","s":"Abjuration","d":"Subject gains a +1 deflection bonus to AC and +1 resistance bonus on saves; you take half of the hit point damage it suffers."},{"n":"Silence","s":"Illusion","d":"Stops all sound in a 20-ft. radius; no spells with verbal components can be cast there."},{"n":"Sound Burst","s":"Evocation","d":"1d8 sonic damage in a 10-ft. spread; Fortitude save or stunned for 1 round."},{"n":"Spiritual Weapon","s":"Evocation","d":"A force weapon attacks with your base attack bonus + Wisdom modifier, dealing 1d8 + 1 per three caster levels (max +5)."},{"n":"Status","s":"Divination","d":"Monitors the condition and position of allies."},{"n":"Summon Monster II","s":"Conjuration","d":"Summons one creature from the 2nd-level list or 1d3 of the same kind from the 1st-level list."},{"n":"Undetectable Alignment","s":"Abjuration","d":"Conceals a creature's alignment."},{"n":"Zone of Truth","s":"Enchantment","d":"Creatures in a 20-ft. radius can't deliberately lie (Will negates)."}],"3":[{"n":"Animate Dead","s":"Necromancy","d":"Creates skeletons or zombies, up to 2 HD per caster level per casting; you control at most 4 HD per caster level."},{"n":"Bestow Curse","s":"Necromancy","d":"Touch curse (Will negates), choose one: −6 to an ability score, or −4 on attack rolls, saves, ability checks, and skill checks, or a 50% chance each turn to take no action."},{"n":"Blindness/Deafness","s":"Necromancy","d":"Blinds or deafens a subject."},{"n":"Contagion","s":"Necromancy","d":"Touch gives the subject a disease of your choice from the list, with no incubation period (Fort negates)."},{"n":"Continual Flame","s":"Evocation","d":"A torch-bright, heatless flame that lasts permanently (uses 50 gp of ruby dust)."},{"n":"Create Food and Water","s":"Conjuration","d":"Food and water for three humans or one horse per caster level for 24 hours."},{"n":"Cure Serious Wounds","s":"Conjuration","d":"Cures 3d8 damage +1/level, maximum +15."},{"n":"Daylight","s":"Evocation","d":"Creates bright light in a 60-ft.-radius area."},{"n":"Deeper Darkness","s":"Evocation","d":"Creates supernatural darkness in a 60-ft.-radius area."},{"n":"Dispel Magic","s":"Abjuration","d":"Ends spells and magical effects: dispel check of 1d20 + caster level (max +10) against DC 11 + the spell's caster level."},{"n":"Glyph of Warding","s":"Abjuration","d":"Inscription that blasts intruders for 1d8 per two caster levels (max 5d8, Reflex half) or releases a stored harmful spell of 3rd level or lower."},{"n":"Helping Hand","s":"Evocation","d":"A ghostly hand finds a described creature within 5 miles and leads it to you if it is willing."},{"n":"Inflict Serious Wounds","s":"Necromancy","d":"Touch deals 3d8 damage +1/level, maximum +15."},{"n":"Invisibility Purge","s":"Evocation","d":"Makes everything invisible visible within 5 ft. per caster level of you."},{"n":"Locate Object","s":"Divination","d":"Senses the direction to a known object."},{"n":"Magic Circle against Chaos/Evil/Good/Law","s":"Abjuration","d":"As protection from chaos/evil/good/law (+2 deflection AC, +2 resistance on saves, mental protection) for everyone in a 10-ft. radius."},{"n":"Magic Vestment","s":"Transmutation","d":"Armor or shield gains a +1 enhancement bonus per four caster levels (max +5)."},{"n":"Meld into Stone","s":"Transmutation","d":"You and up to 100 lb. of gear merge into a block of stone."},{"n":"Obscure Object","s":"Abjuration","d":"Protects an object against divination and scrying."},{"n":"Prayer","s":"Enchantment","d":"You and allies gain a +1 luck bonus on attack rolls, weapon damage rolls, saves, and skill checks; enemies take a −1 penalty on the same rolls."},{"n":"Protection from Energy","s":"Abjuration","d":"Subject is immune to one energy type until the spell has absorbed 12 points per caster level (max 120)."},{"n":"Remove Blindness/Deafness","s":"Conjuration","d":"Cures blindness or deafness."},{"n":"Remove Curse","s":"Abjuration","d":"Frees a creature or object from a curse."},{"n":"Remove Disease","s":"Conjuration","d":"Cures diseases affecting the subject."},{"n":"Searing Light","s":"Evocation","d":"Ray (ranged touch) deals 1d8 per two caster levels (max 5d8); undead take 1d6 per level (max 10d6), or 1d8 per level (max 10d8) if harmed by bright light; constructs and objects 1d6 per two levels (max 5d6)."},{"n":"Speak with Dead","s":"Necromancy","d":"A corpse answers one question per two caster levels."},{"n":"Stone Shape","s":"Transmutation","d":"Sculpts stone into a desired shape."},{"n":"Summon Monster III","s":"Conjuration","d":"Summons one creature from the 3rd-level list, 1d3 from the 2nd-level list, or 1d4+1 from the 1st-level list."},{"n":"Water Breathing","s":"Transmutation","d":"Allows subjects to breathe underwater."},{"n":"Water Walk","s":"Transmutation","d":"Allows a subject to move across water as if solid."},{"n":"Wind Wall","s":"Evocation","d":"Wall of wind: arrows and bolts miss, other normal ranged weapons have a 30% miss chance; blocks gases and Tiny or Small fliers."}],"4":[{"n":"Air Walk","s":"Transmutation","d":"Subject walks through the air as if it were solid."},{"n":"Control Water","s":"Transmutation","d":"Raises or lowers water by up to 2 ft. per caster level."},{"n":"Cure Critical Wounds","s":"Conjuration","d":"Cures 4d8 damage +1/level, maximum +20."},{"n":"Death Ward","s":"Necromancy","d":"Subject is immune to death spells and effects, energy drain, and negative energy effects."},{"n":"Dimensional Anchor","s":"Abjuration","d":"Ray (ranged touch) blocks the subject's extradimensional travel, such as teleport, dimension door, and plane shift."},{"n":"Discern Lies","s":"Divination","d":"Each round you learn whether one subject knowingly lies."},{"n":"Dismissal","s":"Abjuration","d":"Sends one extraplanar creature home: Will save against spell DC − its HD + your caster level; 20% chance it lands on another plane."},{"n":"Divination","s":"Divination","d":"Useful advice about a goal or event within one week; 70% + 1% per caster level chance it is correct (max 90%)."},{"n":"Divine Power","s":"Evocation","d":"Your base attack bonus becomes your character level; you gain a +6 enhancement bonus to Strength and 1 temporary hit point per caster level."},{"n":"Freedom of Movement","s":"Abjuration","d":"Subject moves and attacks normally despite paralysis, slow, web, and similar magic, and automatically succeeds on grapple checks to resist or escape."},{"n":"Giant Vermin","s":"Transmutation","d":"Turns three centipedes, two spiders, or one scorpion into giant versions (size depends on caster level)."},{"n":"Imbue with Spell Ability","s":"Evocation","d":"Transfers some of your prepared 1st- and 2nd-level abjuration, divination, or healing spells to another creature."},{"n":"Inflict Critical Wounds","s":"Necromancy","d":"Touch deals 4d8 damage +1/level, maximum +20."},{"n":"Magic Weapon, Greater","s":"Transmutation","d":"Weapon gains a +1 enhancement bonus on attack and damage rolls per four caster levels (max +5), or affects up to 50 projectiles."},{"n":"Neutralize Poison","s":"Conjuration","d":"Removes poison from a creature or object, or makes a creature immune to poison for 10 min. per level."},{"n":"Planar Ally, Lesser","s":"Conjuration","d":"Asks your deity to send an elemental or outsider of up to 6 HD that performs a task for payment."},{"n":"Poison","s":"Necromancy","d":"Melee touch: 1d10 Constitution damage now and another 1d10 one minute later (Fort negates each)."},{"n":"Repel Vermin","s":"Abjuration","d":"Vermin with less than one-third your HD can't pass the barrier; stronger vermin need a Will save and take 2d6 damage crossing it."},{"n":"Restoration","s":"Conjuration","d":"Dispels negative levels, restores one drained level, cures all ability damage, and restores drained points to one ability score."},{"n":"Sending","s":"Evocation","d":"Sends a message of up to 25 words to a familiar creature, which can reply at once."},{"n":"Spell Immunity","s":"Abjuration","d":"Subject is immune to one spell of 4th level or lower per four caster levels."},{"n":"Summon Monster IV","s":"Conjuration","d":"Summons one creature from the 4th-level list, 1d3 from the 3rd-level list, or 1d4+1 from a lower list."},{"n":"Tongues","s":"Divination","d":"Allows communication in any language."}],"5":[{"n":"Atonement","s":"Abjuration","d":"Removes the burden of misdeeds or restores a lost divine connection; deliberate misdeeds cost you 500 XP."},{"n":"Break Enchantment","s":"Abjuration","d":"Frees subjects from enchantments, transmutations, and curses: caster level check 1d20 + caster level (max +15) against DC 11 + effect's caster level."},{"n":"Command, Greater","s":"Enchantment","d":"As command, but on one creature per level for 1 round per level; each gets a new Will save every round."},{"n":"Commune","s":"Divination","d":"Your deity answers one yes-or-no question per caster level."},{"n":"Cure Light Wounds, Mass","s":"Conjuration","d":"Cures 1d8 + 1 per caster level (max +25) on one creature per level; damages undead instead."},{"n":"Dispel Chaos/Evil/Good/Law","s":"Abjuration","d":"+4 deflection bonus to AC against creatures of the chosen alignment; a touch can send such an outsider home or dispel one spell of that alignment."},{"n":"Disrupting Weapon","s":"Transmutation","d":"Undead struck by the weapon, with HD up to your caster level, must make a Will save or be destroyed."},{"n":"Flame Strike","s":"Evocation","d":"Column of fire deals 1d6 per caster level (max 15d6, Reflex half); half is fire and half divine damage that fire resistance doesn't reduce."},{"n":"Hallow","s":"Evocation","d":"Holy site: magic circle against evil, +4 sacred bonus on turning checks, −4 on commanding undead, no undead rise from bodies there, and one fixed spell effect."},{"n":"Inflict Light Wounds, Mass","s":"Necromancy","d":"Deals 1d8 + 1 per caster level (max +25) to one creature per level (Will half); heals undead instead."},{"n":"Insect Plague","s":"Conjuration","d":"Summons one locust swarm per three caster levels (max 6)."},{"n":"Mark of Justice","s":"Necromancy","d":"Marks a creature with a curse (as bestow curse) that triggers on a behavior you name."},{"n":"Plane Shift","s":"Conjuration","d":"Moves you and up to eight linked creatures to another plane, landing 5–500 miles from the target spot."},{"n":"Raise Dead","s":"Conjuration","d":"Restores life to a creature dead up to one day per caster level; it loses a level (or 2 Con at 1st level). Uses 5,000 gp of diamonds."},{"n":"Righteous Might","s":"Transmutation","d":"You grow one size: +4 size bonus to Strength, +2 size bonus to Constitution, +2 enhancement to natural armor, and damage reduction 3/evil (6 at 12th level, 9 at 15th)."},{"n":"Scrying","s":"Divination","d":"See and hear a creature at any distance (Will negates, modified by how well you know it)."},{"n":"Slay Living","s":"Necromancy","d":"Melee touch kills a living creature; on a successful Fortitude save it takes 3d6 + 1 per caster level damage instead."},{"n":"Spell Resistance","s":"Abjuration","d":"Subject gains spell resistance equal to 12 + your caster level."},{"n":"Summon Monster V","s":"Conjuration","d":"Summons one creature from the 5th-level list, 1d3 from the 4th-level list, or 1d4+1 from a lower list."},{"n":"Symbol of Pain","s":"Necromancy","d":"Triggered rune: creatures within 60 ft. take −4 on attack rolls, skill checks, and ability checks (Fort negates)."},{"n":"Symbol of Sleep","s":"Enchantment","d":"Triggered rune: creatures of 10 HD or less within 60 ft. sleep for 3d6 × 10 minutes (Will negates)."},{"n":"True Seeing","s":"Divination","d":"Subject sees through darkness, illusions, invisibility, and shapechanges to 120 ft."},{"n":"Unhallow","s":"Evocation","d":"Unholy site: magic circle against good, −4 on turning checks, +4 profane bonus on rebuking, and one fixed spell effect."},{"n":"Wall of Stone","s":"Conjuration","d":"Stone wall of up to one 5-ft. square per level, 1 inch thick per four levels; it must rest on existing stone."}],"6":[{"n":"Animate Objects","s":"Transmutation","d":"Animates one Small object per caster level (larger objects count as more) to fight for you."},{"n":"Antilife Shell","s":"Abjuration","d":"10-ft. hemisphere that keeps out most living creatures (not constructs, elementals, outsiders, or undead)."},{"n":"Banishment","s":"Abjuration","d":"Banishes up to 2 HD per caster level of extraplanar creatures (Will negates); hated items give +1 on the SR check and +2 to the DC each."},{"n":"Bear's Endurance, Mass","s":"Transmutation","d":"One creature per level gains a +4 enhancement bonus to Constitution."},{"n":"Blade Barrier","s":"Evocation","d":"Wall of force blades deals 1d6 per caster level (max 15d6, Reflex half) to anything passing through."},{"n":"Bull's Strength, Mass","s":"Transmutation","d":"One creature per level gains a +4 enhancement bonus to Strength."},{"n":"Create Undead","s":"Necromancy","d":"Turns a corpse into a ghoul, ghast, mummy, or mohrg, depending on your caster level."},{"n":"Cure Moderate Wounds, Mass","s":"Conjuration","d":"Cures 2d8 + 1 per caster level (max +30) on one creature per level; damages undead instead."},{"n":"Dispel Magic, Greater","s":"Abjuration","d":"As dispel magic, but the dispel check is 1d20 + caster level (max +20) and it can remove curses."},{"n":"Eagle's Splendor, Mass","s":"Transmutation","d":"One creature per level gains a +4 enhancement bonus to Charisma."},{"n":"Find the Path","s":"Divination","d":"Shows the subject the shortest physical route to a place."},{"n":"Forbiddance","s":"Abjuration","d":"Blocks all planar travel and summoning in the area; creatures of a different alignment take 6d6 (one axis) or 12d6 (both axes) when entering (Will half)."},{"n":"Geas/Quest","s":"Enchantment","d":"Orders a creature to carry out a task (no save); each day it doesn't try, it takes 3d6 damage and must save or be sickened."},{"n":"Glyph of Warding, Greater","s":"Abjuration","d":"As glyph of warding, but the blast deals up to 10d8 or it stores a spell of 6th level or lower."},{"n":"Harm","s":"Necromancy","d":"Touch deals 10 damage per caster level (max 150; Will half); can't drop the target below 1 hp. Heals undead."},{"n":"Heal","s":"Conjuration","d":"Cures 10 hit points per caster level (max 150) and ends ability damage, blindness, confusion, disease, fatigue, nausea, poison, stun, and more."},{"n":"Heroes' Feast","s":"Conjuration","d":"Feast for one creature per level. After 1 hour: 1d8 + 1 per two levels (max +10) temporary hit points, +1 morale bonus on attack rolls and Will saves, and immunity to poison and fear for 12 hours."},{"n":"Inflict Moderate Wounds, Mass","s":"Necromancy","d":"Deals 2d8 + 1 per caster level (max +30) to one creature per level (Will half); heals undead instead."},{"n":"Owl's Wisdom, Mass","s":"Transmutation","d":"One creature per level gains a +4 enhancement bonus to Wisdom."},{"n":"Planar Ally","s":"Conjuration","d":"Calls one creature of up to 12 HD, or two of the same kind totaling 12 HD, for a task (250 XP)."},{"n":"Summon Monster VI","s":"Conjuration","d":"Summons one creature from the 6th-level list, 1d3 from the 5th-level list, or 1d4+1 from a lower list."},{"n":"Symbol of Fear","s":"Necromancy","d":"Triggered rune: creatures within 60 ft. are panicked for 1 round per caster level (Will negates)."},{"n":"Symbol of Persuasion","s":"Enchantment","d":"Triggered rune: creatures within 60 ft. are charmed by you for 1 hour per caster level (Will negates)."},{"n":"Undeath to Death","s":"Necromancy","d":"Destroys 1d4 HD of undead per caster level (max 20d4) in a 40-ft. burst; undead of 9 HD or more are unaffected (Will negates)."},{"n":"Wind Walk","s":"Transmutation","d":"You and one creature per three caster levels become vapor and fly at up to 600 ft. per round (60 mph)."},{"n":"Word of Recall","s":"Conjuration","d":"Teleports you, and others up to your load limit, to your chosen sanctuary."}],"7":[{"n":"Blasphemy","s":"Evocation","d":"Nonevil creatures that hear it are dazed, weakened (−2d6 Str), paralyzed, or killed, depending on their HD versus your caster level (no save)."},{"n":"Control Weather","s":"Transmutation","d":"Changes the weather within a 2-mile radius to anything that fits the season."},{"n":"Cure Serious Wounds, Mass","s":"Conjuration","d":"Cures 3d8 + 1 per caster level (max +35) on one creature per level; damages undead instead."},{"n":"Destruction","s":"Necromancy","d":"Kills the subject and consumes its body; on a successful Fortitude save it takes 10d6 damage instead."},{"n":"Dictum","s":"Evocation","d":"Nonlawful creatures that hear it are deafened, slowed, paralyzed, or killed, depending on their HD versus your caster level (no save)."},{"n":"Ethereal Jaunt","s":"Transmutation","d":"You become ethereal."},{"n":"Holy Word","s":"Evocation","d":"Nongood creatures that hear it are deafened, blinded, paralyzed, or killed, depending on their HD versus your caster level (no save)."},{"n":"Inflict Serious Wounds, Mass","s":"Necromancy","d":"Deals 3d8 + 1 per caster level (max +35) to one creature per level (Will half); heals undead instead."},{"n":"Refuge","s":"Conjuration","d":"Prepares an item to transport its possessor to you."},{"n":"Regenerate","s":"Conjuration","d":"Regrows lost limbs and organs, cures 4d8 + 1 per caster level (max +35), and ends fatigue, exhaustion, and nonlethal damage."},{"n":"Repulsion","s":"Abjuration","d":"Prevents creatures from approaching you."},{"n":"Restoration, Greater","s":"Conjuration","d":"As restoration, but it dispels all negative levels, restores all drained levels, and restores all ability points."},{"n":"Resurrection","s":"Conjuration","d":"Fully restores a creature dead up to 10 years per caster level, from any small part of its body; it still loses a level."},{"n":"Scrying, Greater","s":"Divination","d":"As scrying, but cast in 1 standard action, lasts 1 hour per level, and detection spells work through the sensor."},{"n":"Summon Monster VII","s":"Conjuration","d":"Summons one creature from the 7th-level list, 1d3 from the 6th-level list, or 1d4+1 from a lower list."},{"n":"Symbol of Stunning","s":"Transmutation","d":"Triggered rune: creatures within 60 ft. are stunned for 1d6 rounds (Will negates)."},{"n":"Symbol of Weakness","s":"Necromancy","d":"Triggered rune: creatures within 60 ft. take 3d6 Strength damage (Fort negates)."},{"n":"Word of Chaos","s":"Evocation","d":"Nonchaotic creatures that hear it are deafened, stunned, confused, or killed, depending on their HD versus your caster level (no save)."}],"8":[{"n":"Antimagic Field","s":"Abjuration","d":"Suppresses magic in a 10-ft.-radius field."},{"n":"Cloak of Chaos","s":"Abjuration","d":"One creature per level: +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against lawful spells, mental protection; lawful attackers are confused."},{"n":"Create Greater Undead","s":"Necromancy","d":"Turns a corpse into a shadow, wraith, spectre, or devourer, depending on your caster level."},{"n":"Cure Critical Wounds, Mass","s":"Conjuration","d":"Cures 4d8 + 1 per caster level (max +40) on one creature per level; damages undead instead."},{"n":"Dimensional Lock","s":"Abjuration","d":"Blocks teleportation and planar travel in an area."},{"n":"Discern Location","s":"Divination","d":"Reveals the exact location of a creature or object."},{"n":"Earthquake","s":"Evocation","d":"A 1-round tremor in an 80-ft. radius knocks creatures down, collapses structures, and opens fissures."},{"n":"Fire Storm","s":"Evocation","d":"Flames deal 1d6 fire damage per caster level (max 20d6, Reflex half) to creatures in the area."},{"n":"Holy Aura","s":"Abjuration","d":"One creature per level: +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against evil spells, mental protection; evil attackers are blinded."},{"n":"Inflict Critical Wounds, Mass","s":"Necromancy","d":"Deals 4d8 + 1 per caster level (max +40) to one creature per level (Will half); heals undead instead."},{"n":"Planar Ally, Greater","s":"Conjuration","d":"Calls one creature of up to 18 HD, or up to three of the same kind totaling 18 HD, for a task (500 XP)."},{"n":"Shield of Law","s":"Abjuration","d":"One creature per level: +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against chaotic spells, mental protection; chaotic attackers are slowed."},{"n":"Spell Immunity, Greater","s":"Abjuration","d":"As spell immunity, but it covers spells of 8th level or lower."},{"n":"Summon Monster VIII","s":"Conjuration","d":"Summons one creature from the 8th-level list, 1d3 from the 7th-level list, or 1d4+1 from a lower list."},{"n":"Symbol of Death","s":"Necromancy","d":"Triggered rune kills creatures within 60 ft. with up to 150 total hit points (Fort negates)."},{"n":"Symbol of Insanity","s":"Enchantment","d":"Triggered rune: creatures within 60 ft. become permanently insane (Will negates)."},{"n":"Unholy Aura","s":"Abjuration","d":"One creature per level: +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against good spells, mental protection; good attackers are weakened."}],"9":[{"n":"Astral Projection","s":"Necromancy","d":"Projects your astral body and companions into the Astral Plane."},{"n":"Energy Drain","s":"Necromancy","d":"Bestows 2d4 negative levels."},{"n":"Etherealness","s":"Transmutation","d":"You and one willing creature per three caster levels become ethereal."},{"n":"Gate","s":"Conjuration","d":"Creates a planar connection for travel or calling."},{"n":"Heal, Mass","s":"Conjuration","d":"As heal, on several creatures within 30 ft. of each other; up to 250 hit points each."},{"n":"Implosion","s":"Evocation","d":"Each round you concentrate, one corporeal creature collapses and dies (Fort negates)."},{"n":"Miracle","s":"Evocation","d":"Duplicates any cleric spell of 8th level or lower, any other spell of 7th level or lower, or a similar effect."},{"n":"Soul Bind","s":"Necromancy","d":"Traps the soul of a creature dead up to 1 round per level in a black sapphire, so it can't be raised."},{"n":"Storm of Vengeance","s":"Conjuration","d":"Storm cloud deafens, then rains acid, lightning, and hail on those below for as long as you concentrate."},{"n":"Summon Monster IX","s":"Conjuration","d":"Summons one creature from the 9th-level list, 1d3 from the 8th-level list, or 1d4+1 from a lower list."},{"n":"True Resurrection","s":"Conjuration","d":"Fully restores a dead creature without requiring its remains."}]},"magic":{"1":{"n":"Magic Aura","s":"Illusion (Glamer)","d":"Makes one object of up to 5 lb. per level read as nonmagical or as a magic item or spell you choose, for 1 day per level; identify sees through it on a Will save."},"2":{"n":"Identify","s":"Divination","d":"Reveals all magic properties of one item, how to activate them, and charges left (takes 1 hour; uses a 100 gp pearl; doesn't work on artifacts)."},"3":{"n":"Dispel Magic","s":"Abjuration","d":"Ends spells and magical effects: dispel check of 1d20 + caster level (max +10) against DC 11 + the spell's caster level."},"4":{"n":"Imbue with Spell Ability","s":"Evocation","d":"Transfers some of your prepared 1st- and 2nd-level abjuration, divination, or healing spells to another creature."},"5":{"n":"Spell Resistance","s":"Abjuration","d":"Grants the subject spell resistance equal to 12 + caster level."},"6":{"n":"Antimagic Field","s":"Abjuration","d":"10-ft.-radius field around you suppresses all spells, spell-like and supernatural abilities, and magic items for 10 min. per level."},"7":{"n":"Spell Turning","s":"Abjuration","d":"Turns 1d4+6 spell levels of spells targeted at you back on their caster (not area, effect, or touch spells)."},"8":{"n":"Protection from Spells","s":"Abjuration","d":"Up to one creature per 4 levels gains a +8 resistance bonus on saves vs. spells and spell-like abilities."},"9":{"n":"Mage's Disjunction","s":"Abjuration","d":"Ends every spell in a 40-ft. burst; each magic item must make a Will save or become mundane (1% per level chance against artifacts)."}},"balance":{"1":{"n":"Make Whole","s":"Transmutation","d":"Fully repairs one object, even with multiple breaks — but not its lost magic.","ref":"PH p. 252","full":"Repairs a broken object of any material, even one with several breaks, making it as strong as new. It works on objects up to 10 cubic feet per caster level.\n\nLimits: it does not restore the magical properties of a broken magic item, and it cannot fix broken rods, staffs, or wands. It cannot repair objects that were warped, burned, disintegrated, ground to powder, melted, or vaporized. It has no effect on creatures, including constructs."},"2":{"n":"Calm Emotions","s":"Enchantment (Compulsion) [Mind-Affecting]","d":"Calms creatures in a 20-ft. radius; suppresses rage, morale bonuses, fear, and confusion.","ref":"PH p. 207","full":"Calms agitated creatures in the area. You have no control over them, but they cannot take violent or destructive actions, though they can still defend themselves. Any aggressive act or damage against a calmed creature immediately breaks the spell for all calmed creatures.\n\nWhile it lasts, it suppresses (does not dispel) morale bonuses such as bless, good hope, rage, a barbarian's rage, or a bard's inspire courage. It also suppresses fear effects and removes confusion. When the spell ends, suppressed effects resume if their own duration has not expired.\n\nYou must concentrate to maintain it, up to 1 round per level."},"3":{"n":"Clarity of Mind","s":"Abjuration","d":"+4 insight bonus on saves vs. mind-affecting effects; reroll one failed concealment miss chance.","ref":"Spell Compendium p. 46","full":"The touched creature gains a +4 insight bonus on saving throws against all mind-affecting spells and effects.\n\nIn addition, if the subject attacks a creature that has concealment and fails the miss chance roll, it can reroll that miss chance once to see whether the attack actually hits. This works against any source of concealment.\n\nLasts 1 hour per caster level."},"4":{"n":"Dismissal","s":"Abjuration","d":"Sends one extraplanar creature back to its home plane (Will negates).","ref":"PH p. 222","full":"Forces one extraplanar creature off your current plane and back toward its own. The creature makes a Will save against a modified DC: the spell's normal DC, minus the creature's Hit Dice, plus your caster level.\n\nIf it fails, it is instantly sent away. There is a 20% chance it ends up on a random plane other than its home plane."},"5":{"n":"Sanctuary, Mass","s":"Abjuration","d":"Wards one creature/level: enemies must save to attack them; attacking ends the ward.","ref":"Spell Compendium p. 179","full":"Works like sanctuary, but on one creature per caster level (no two more than 30 ft. apart).\n\nAny opponent trying to strike or directly attack a warded creature, even with a targeted spell, must make a Will save. On a success, it attacks normally and is unaffected by that casting. On a failure, that part of its action is lost and it cannot directly attack that warded creature for the rest of the duration.\n\nThe ward does not protect against area or effect spells. A warded creature that attacks breaks the spell for itself. It can still cast nonattack spells, such as healing, bless, or summoning, or otherwise act freely.\n\nLasts 1 round per caster level. Spell resistance does not apply."},"6":{"n":"Banishment","s":"Abjuration","d":"Banishes up to 2 HD/level of extraplanar creatures back to their home planes.","ref":"PH p. 202","full":"A stronger dismissal. It forces extraplanar creatures out of your home plane, up to 2 Hit Dice of creatures per caster level. Each gets a Will save to negate.\n\nPresenting an object or substance the targets hate, fear, or oppose improves your odds. Each such item gives +1 on your caster level check to beat their spell resistance and +2 to the save DC. Certain rare items count double (+2 on the check and +4 to the DC)."},"7":{"n":"Word of Balance","s":"Evocation [Sonic]","d":"Punishes LG, CG, LE, and CE creatures by Hit Dice: nauseated up to killed. Neutral-aligned creatures are unaffected.","ref":"Spell Compendium p. 242","full":"You speak a word of balance. Every lawful good, chaotic good, lawful evil, or chaotic evil creature within 30 ft. that hears it suffers effects based on its Hit Dice, with no saving throw. The effects stack:\n• HD equal to your caster level: nauseated.\n• HD up to caster level −1: weakened and nauseated.\n• HD up to caster level −5: paralyzed, weakened, and nauseated.\n• HD up to caster level −10: killed.\n\nNauseated means only a single move action for 1 round, though it can still defend itself. Weakened means Strength drops by 2d6 for 2d4 rounds. Paralyzed means helpless for 1d10 minutes. Killed means living creatures die and undead are destroyed.\n\nIf you cast it on your home plane, every LG, CG, LE, or CE elemental or outsider in the area is also banished to its home plane for at least 24 hours. It can resist with a Will save at −4, and this happens whether or not it hears the word.\n\nCreatures whose HD exceed your caster level are unaffected. Creatures with any neutral component in their alignment (LN, CN, NG, NE, N) are never affected."},"8":{"n":"Protection from Spells","s":"Abjuration","d":"Up to one creature per 4 levels gains a +8 resistance bonus on saves vs. spells and spell-like abilities.","ref":"PH p. 267","full":"Each subject gains a +8 resistance bonus on saving throws against spells and spell-like abilities. It does not apply against supernatural or extraordinary abilities. You can protect one creature per four caster levels, and it lasts 10 minutes per level.\n\nMaterial component: a diamond worth at least 500 gp, crushed and sprinkled over the targets. Focus: a 1,000 gp diamond or gem for each subject, which that subject must carry for the whole duration. A subject who loses its gem loses the protection."},"9":{"n":"Weighed in the Balance","s":"Necromancy","d":"30-ft. burst: LG, CG, LE, and CE creatures take an inflict critical wounds effect, other non-neutral creatures inflict moderate wounds; true neutral creatures and all undead get a heal effect (Will negates).","ref":"Spell Compendium p. 238","full":"A warm orange fire radiates from you and judges every creature within 30 ft. by alignment. It harms most those farthest from balance.\n• Living LG, CG, LE, or CE creatures take an inflict critical wounds effect.\n• Living NG, LN, CN, or NE creatures take an inflict moderate wounds effect.\n• Living true neutral creatures receive a heal effect.\n• All undead receive the heal effect as well, which damages them instead of healing.\n\nEach creature can attempt a Will save to negate the effect. Spell resistance applies."}}};
// Other domains Caelian can swap to (see DOMAINS in app.js). Spell lists checked against the SRD and Realms Help.
DATA.earth={"1":{"n":"Magic Stone","s":"Transmutation","d":"Up to three pebbles become +1 sling stones or thrown weapons that deal 1d6+1 damage (2d6+2 against undead)."},"2":{"n":"Soften Earth and Stone","s":"Transmutation [Earth]","d":"Turns natural earth into mud or loose sand, or natural stone into clay, in one 10-ft. square per level. Mud traps creatures for 1d2 rounds (Reflex negates; half speed after)."},"3":{"n":"Stone Shape","s":"Transmutation [Earth]","d":"Reshapes stone up to 10 cu. ft. + 1 cu. ft. per level into a rough shape; 30% chance that moving parts don't work."},"4":{"n":"Spike Stones","s":"Transmutation [Earth]","d":"One 20-ft. square per level grows hidden spikes: half speed, 1d8 piercing per 5 ft. moved, and Reflex save or speed halved for 24 hours."},"5":{"n":"Wall of Stone","s":"Conjuration (Creation) [Earth]","d":"Stone wall of up to one 5-ft. square per level, 1 inch thick per four levels; it must rest on existing stone."},"6":{"n":"Stoneskin","s":"Abjuration","d":"Damage reduction 10/adamantine until it has prevented 10 points per caster level (max 150). Uses 250 gp of diamond dust."},"7":{"n":"Earthquake","s":"Evocation [Earth]","d":"A one-round tremor in an 80-ft.-radius spread knocks creatures down, collapses structures, and opens fissures."},"8":{"n":"Iron Body","s":"Transmutation","d":"Your body becomes iron: damage reduction 15/adamantine, many immunities, half damage from acid and fire, +6 enhancement bonus to Strength, −6 Dexterity, half speed."},"9":{"n":"Elemental Swarm","s":"Conjuration (Summoning) [see text]","d":"Summons 2d4 Large earth elementals, then 1d4 Huge ones 10 minutes later, then one greater elemental 10 minutes after that. Cast as an earth spell only."}};
DATA.nature={"1":{"n":"Trance","s":"Divination","d":"You go into a trance and sense spirits, curses and lasting magic around you.","ref":"Oriental Adventures","url":"https://www.realmshelps.net/magic/spell/Trance","full":"You fall into a deep trance and can't move, speak or take any action while it lasts. Each round you stay in the trance, you sense one lesser spirit, greater spirit, curse, permanent magical effect or haunting within 120 ft. of you. You learn only its general kind (for example a nature spirit or an evil haunting); you can't communicate with it or learn anything else about it.\n\nWhat you learn is enough to target that spirit later with Commune with Lesser Spirit or a similar spell."},"2":{"n":"Commune with Lesser Spirit","s":"Divination","d":"A spirit of 4 HD or less answers one question per two caster levels.","ref":"Oriental Adventures","url":"https://www.realmshelps.net/magic/spell/Commune_With_Lesser_Spirit","full":"You contact a local spirit with 4 Hit Dice or fewer. You must know which spirit it is (Trance can tell you) and be within 10 ft. of where it lives. You can ask one question per two caster levels; questions not asked before the spell ends are lost.\n\nThe spirit only knows about its own immediate area: the spirit of a great tree in a village knows nothing of events outside that village. Spirits answer literally and don't volunteer information. Good spirits usually try to help; evil spirits always twist what they say, though their answers are generally literally true.\n\nIf the spirit's alignment differs from yours, it gets a Will save to resist. The spell fails if the spirit has already been the target of Commune with Lesser Spirit within the past week.\n\nMaterial component: incense and a small offering worth 10 gp."},"3":{"n":"Possess Animal","s":"Necromancy","d":"Your spirit enters a normal animal and controls its body while yours lies lifeless.","ref":"Oriental Adventures","url":"https://www.realmshelps.net/magic/spell/Possess_Animal","full":"You project your spirit into a normal animal (not a beast, magical beast, vermin or other monster type) with fewer Hit Dice than your level, and it acts as you direct. Your own body lies lifeless while the spell lasts. The animal's soul stays in its body but has no control while you are there.\n\nIn the animal's body you keep your Intelligence, Wisdom, Charisma, level, class, base attack bonus, base save bonuses, alignment and mental abilities. The body keeps its Strength, Dexterity, Constitution, hit points, natural abilities and automatic abilities. You can't activate its extraordinary or supernatural abilities.\n\nFor every 2 points of damage the animal's body takes, you take 1. If the animal is killed while you possess it, you must make a DC 10 Fortitude save or die too. If your own body is destroyed while you are away, you die when the spell ends.\n\nMaterial component: a bowl of incense and a morsel of food the animal likes."},"4":{"n":"Elemental Ward","s":"Abjuration","d":"With a fearsome cry you drive elementals of one type out of a 60-ft. area around you.","ref":"Oriental Adventures","url":"https://www.realmshelps.net/magic/spell/Elemental_Ward","full":"Choose one type of elemental (air, earth, fire or water). When you cast the spell with a fearsome cry, every elemental of that type within the 60-ft. emanation around you must make a Will save or flee the area. The spell ends if you try to force the barrier against an elemental that has failed its save.\n\nMaterial component: a small amount of the element opposed to the warded type: fire against water elementals, earth against air, air against earth, or water against fire."},"5":{"n":"Commune with Greater Spirit","s":"Divination","d":"Any spirit, whatever its Hit Dice, answers one yes-or-no question per caster level.","ref":"Oriental Adventures","url":"https://www.realmshelps.net/magic/spell/Commune_With_Greater_Spirit","full":"This works like Commune with Lesser Spirit, but you can contact any spirit, whatever its Hit Dice. You can ask one question per caster level, and each must be answerable with yes or no. The answers are correct as far as the spirit knows. \"Unclear\" is a valid answer, since even great spirits don't know everything. Where a one-word answer would be misleading or against the spirit's interests, the DM may give a short phrase of five words or less instead.\n\nThe book lists only components and target for this spell. Its other entries follow Commune with Lesser Spirit.\n\nMaterial component: incense and a small offering worth 25 gp. XP cost: 100 XP."},"6":{"n":"Transport via Plants","s":"Conjuration (Teleportation)","d":"Step into a living plant of Medium size or larger and out of another of the same kind any distance away on the same plane; bring one Medium creature per three levels."},"7":{"n":"Control Weather","s":"Transmutation","d":"Changes the weather within a 2-mile radius over 10 minutes."},"8":{"n":"Animal Shapes","s":"Transmutation","d":"Up to one willing creature per level turns into the same animal, with max HD equal to its HD or your caster level (max 20), for 1 hour per level."},"9":{"n":"Shapechange","s":"Transmutation","d":"You take the form of any nonunique creature of up to your caster level in HD (max 25) and can change form once per round as a free action."}};
DATA.law={"1":{"n":"Protection from Chaos","s":"Abjuration [Lawful]","d":"+2 deflection bonus to AC and +2 resistance bonus on saves against chaotic creatures, blocks mental control, and keeps summoned chaotic creatures from touching the subject."},"2":{"n":"Calm Emotions","s":"Enchantment (Compulsion) [Mind-Affecting]","d":"Calms creatures in a 20-ft. radius and suppresses rage, morale bonuses, fear, and confusion."},"3":{"n":"Magic Circle against Chaos","s":"Abjuration [Lawful]","d":"As protection from chaos, but in a 10-ft. radius around the touched creature, lasting 10 min. per level."},"4":{"n":"Order's Wrath","s":"Evocation [Lawful]","d":"30-ft. cube burst: chaotic creatures take 1d8 per two levels (max 5d8; chaotic outsiders 1d6 per level, max 10d6) and are dazed 1 round. Will half and no daze. Neutral creatures take half. Lawful creatures are unaffected."},"5":{"n":"Dispel Chaos","s":"Abjuration [Lawful]","d":"+4 deflection bonus to AC against chaotic creatures. A touch can drive a chaotic outsider back to its plane or end a chaotic enchantment or spell."},"6":{"n":"Hold Monster","s":"Enchantment (Compulsion) [Mind-Affecting]","d":"As hold person, but it paralyzes any living creature (Will negates, new save each round)."},"7":{"n":"Dictum","s":"Evocation [Lawful, Sonic]","d":"Nonlawful creatures within 40 ft. that hear it are deafened (1d4 rounds), slowed (2d4 rounds), paralyzed (1d10 min.), or killed, depending on their HD versus your caster level (no save)."},"8":{"n":"Shield of Law","s":"Abjuration [Lawful]","d":"One creature per level gains a +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against chaotic spells, and protection from possession. Chaotic attackers can be slowed."},"9":{"n":"Summon Monster IX","s":"Conjuration (Summoning) [Lawful]","d":"Calls a creature from the 9th-level summon monster list to fight for you. Cast as a law spell only."}};
DATA.good={"1":{"n":"Protection from Evil","s":"Abjuration [Good]","d":"+2 deflection bonus to AC and +2 resistance bonus on saves against evil creatures, blocks mental control, and keeps summoned evil creatures from touching the subject."},"2":{"n":"Aid","s":"Enchantment (Compulsion) [Mind-Affecting]","d":"+1 morale bonus on attack rolls and on saves against fear, plus 1d8 + 1 per level temporary hit points (max 1d8 + 10)."},"3":{"n":"Magic Circle against Evil","s":"Abjuration [Good]","d":"As protection from evil, but in a 10-ft. radius around the touched creature, lasting 10 min. per level."},"4":{"n":"Holy Smite","s":"Evocation [Good]","d":"20-ft. burst: evil creatures take 1d8 per two levels (max 5d8; evil outsiders 1d6 per level, max 10d6) and are blinded 1 round. Will half and no blindness. Neutral creatures take half. Good creatures are unaffected."},"5":{"n":"Dispel Evil","s":"Abjuration [Good]","d":"+4 deflection bonus to AC against evil creatures. A touch can drive an evil outsider back to its plane or end an evil enchantment or spell."},"6":{"n":"Blade Barrier","s":"Evocation [Force]","d":"Wall of force blades deals 1d6 per level (max 15d6, Reflex half) to anything passing through; gives cover (+4 AC, +2 Reflex) to attacks through it."},"7":{"n":"Holy Word","s":"Evocation [Good, Sonic]","d":"Nongood creatures within 40 ft. that hear it are deafened (1d4 rounds), blinded (2d4 rounds), paralyzed (1d10 min.), or killed, depending on their HD versus your caster level (no save)."},"8":{"n":"Holy Aura","s":"Abjuration [Good]","d":"One creature per level gains a +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against evil spells, and protection from possession. Evil attackers can be blinded."},"9":{"n":"Summon Monster IX","s":"Conjuration (Summoning) [Good]","d":"Calls a creature from the 9th-level summon monster list to fight for you. Cast as a good spell only."}};
DATA.protection={"1":{"n":"Sanctuary","s":"Abjuration","d":"Opponents must make a Will save to attack the warded creature; the ward ends if it attacks."},"2":{"n":"Shield Other","s":"Abjuration","d":"The subject gains a +1 deflection bonus to AC and +1 resistance bonus on saves, and you take half of the damage it suffers."},"3":{"n":"Protection from Energy","s":"Abjuration","d":"Absorbs 12 points per level (max 120) of damage from one chosen energy type."},"4":{"n":"Spell Immunity","s":"Abjuration","d":"The subject becomes immune to one spell of 4th level or lower per four caster levels."},"5":{"n":"Spell Resistance","s":"Abjuration","d":"The subject gains spell resistance equal to 12 + your caster level."},"6":{"n":"Antimagic Field","s":"Abjuration","d":"10-ft.-radius field around you suppresses all spells, spell-like and supernatural abilities, and magic items for 10 min. per level."},"7":{"n":"Repulsion","s":"Abjuration","d":"Creatures within up to 10 ft. per level of you can't move toward you for 1 round per level (Will negates)."},"8":{"n":"Mind Blank","s":"Abjuration","d":"For 24 hours the subject is immune to mind-affecting effects and to divinations and scrying that would find it."},"9":{"n":"Prismatic Sphere","s":"Abjuration","d":"10-ft. sphere of seven colored layers around you; each layer blocks a kind of attack and harms creatures passing through it. Creatures under 8 HD that see it are blinded for 2d4 × 10 minutes."}};
DATA.inquisition={"1":{"n":"Detect Chaos","s":"Divination","d":"Reveals chaotic creatures, spells, and objects in a 60-ft. cone."},"2":{"n":"Zone of Truth","s":"Enchantment (Compulsion) [Mind-Affecting]","d":"Creatures in a 20-ft. radius can't knowingly lie (Will negates)."},"3":{"n":"Detect Thoughts","s":"Divination [Mind-Affecting]","d":"Reads surface thoughts in a 60-ft. cone: minds present (round 1), number and Intelligence of each (round 2), surface thoughts (round 3; Will negates)."},"4":{"n":"Discern Lies","s":"Divination","d":"Shows you when the chosen creatures knowingly lie."},"5":{"n":"True Seeing","s":"Divination","d":"The subject sees through darkness, illusions, and shapechanges to the true form of things."},"6":{"n":"Geas/Quest","s":"Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]","d":"Orders a creature to carry out a task. Refusing makes it sicken and weaken."},"7":{"n":"Dictum","s":"Evocation [Lawful, Sonic]","d":"Nonlawful creatures within 40 ft. that hear it are deafened (1d4 rounds), slowed (2d4 rounds), paralyzed (1d10 min.), or killed, depending on their HD versus your caster level (no save)."},"8":{"n":"Shield of Law","s":"Abjuration [Lawful]","d":"One creature per level gains a +4 deflection bonus to AC and +4 resistance bonus on saves, SR 25 against chaotic spells, and protection from possession. Chaotic attackers can be slowed."},"9":{"n":"Imprisonment","s":"Abjuration","d":"Entombs a touched creature in suspended animation far beneath the earth (Will negates; −4 on the save if you know its name and history)."}};
